                cur = ""
            continue
        if cur and ch.isupper():
            nxt = ident[i + 1] if i + 1 < len(ident) else ""
            last = cur[-1]
            if last.islower() or last.isdigit() or (last.isupper() and nxt.islower()):
                words.append(cur)
                cur = ""
